/* eslint-disable no-unused-vars */
import React, { useState, Suspense, useEffect, useRef } from 'react';
import { useForm, Controller, useWatch, useFormState, useFieldArray } from 'react-hook-form';
import classNames from 'classnames';
import { useAsyncResource } from 'use-async-resource';
import { __, sprintf } from '@wordpress/i18n';
import BeatLoader from 'react-spinners/BeatLoader';

import {
	TextControl,
	Button,
	RadioControl,
	ToggleControl,
	CheckboxControl,
} from '@wordpress/components';
import Spinner from '../../components/icons/Spinner';
import ClipboardCheck from '../../components/icons/ClipboardCheck';
import sendCommand from '../../../SendCommand';
import CircularExclamationIcon from '../../components/icons/CircularExplanation';
import Notice from '../../components/Notice';
import ErrorBoundary from '../../components/ErrorBoundary';

const retrieveConvertKitOptions = () => {
	return sendCommand( 'sce_get_convertkit_options', {
		nonce: sceIntegrations.ck_get_nonce,
	} );
};

const ConvertKit = ( props ) => {
	const [ defaults, getDefaults ] = useAsyncResource(
		retrieveConvertKitOptions,
		[]
	);
	return (
		<ErrorBoundary
			fallback={
				<p>
					{ __( 'Could not load ConvertKit Settings.', 'comment-edit-pro' ) }
					<br />
					<a
						href="https://dlxplugins.com/support/"
						target="_blank"
						rel="noopener noreferrer"
					>
						DLX Plugins Support
					</a>
				</p>
			}
		>
			<Suspense
				fallback={
					<>
						<h2>{ __( 'ConvertKit', 'comment-edit-pro' ) }</h2>
						<BeatLoader
							color={ '#9c68b0' }
							loading={ true }
							cssOverride={ true }
							size={ 25 }
							speedMultiplier={ 0.65 }
						/>
					</>
				}
			>
				<Interface defaults={ defaults } { ...props } />
			</Suspense>
		</ErrorBoundary>
	);
};

const Interface = ( props ) => {
	const tagInput = useRef( null );
	const { defaults } = props;
	const response = defaults();
	const { data, success } = response.data;
	const [ saving, setSaving ] = useState( false );
	const [ isSaved, setIsSaved ] = useState( false );
	const [ resetting, setResetting ] = useState( false );
	const [ isReset, setIsReset ] = useState( false );
	const [ credentialsRefreshing, setCredentialsRefreshing ] = useState( false );
	const [ isRefreshingFormsAndTags, setIsRefreshingFormsAndTags ] =
		useState( false );
	const [ isAddingTag, setIsAddingTag ] = useState( false );

	const {
		register,
		control,
		handleSubmit,
		setValue,
		getValues,
		reset,
		setError,
		clearErrors,
		trigger,
	} = useForm( {
		defaultValues: {
			enableConvertKit: data.enableConvertKit,
			apiValid: data.apiValid,
			apiKey: data.apiKey,
			secretKey: data.secretKey,
			signUpLabel: data.signUpLabel,
			checkboxEnabled: data.checkboxEnabled,
			formOrTag: data.formOrTag,
			forms: data.forms,
			tags: data.tags ?? [ { label: '', value: '', selected: '' } ],
			selectedForm: data.selectedForm,
			selectedTags: [ { label: '', value: '', selected: '' } ],
			tagInput: '',
		},
	} );
	// Get tags array.
	const { fields: tagFields, append: appendTag, remove: removeTag } = useFieldArray(
		{
			control,
			name: 'selectedTags',
		}
	);
	const formValues = useWatch( { control } );
	const { errors, isDirty, dirtyFields, touchedFields } = useFormState( {
		control,
	} );

	/**
	 * Check if we need to re-connect or initially connect to the ConvertKit API.
	 *
	 * @return {boolean} true if we need to re-connect, false if not.
	 */
	const needsCredentialRefresh = () => {
		if ( ! getValues( 'apiValid' ) ) {
			return true;
		}
		if ( isDirty && ( dirtyFields.apiKey || dirtyFields.secretKey ) ) {
			return true;
		}
		return false;
	};

	/**
	 * Check if we can save the form.
	 *
	 * @return {boolean} true to show the save button, false to hide it.
	 */
	const canShowSaveButton = () => {
		const forms = getValues( 'forms' );
		const tags = getValues( 'tags' );

		if ( getValues( 'apiValid' ) && ( forms.length === 0 && tags.length === 0 ) ) {
			return false;
		}
		if ( ! getValues( 'apiValid' ) && isDirty ) {
			return false;
		}
		if ( needsCredentialRefresh() ) {
			return false;
		}

		// Check to see if any tags are selected.
		if ( getValues( 'formOrTag' ) === 'tag' ) {
			if ( tags.length === 0 ) {
				return false;
			}
			let selected = false;
			tags.forEach( ( tag ) => {
				if ( tag.selected ) {
					selected = true;
				}
			} );
			if ( ! selected ) {
				return false;
			}
		}
		return true;
	};

	const hasErrors = () => {
		return Object.keys( errors ).length > 0;
	};

	const onSubmit = ( formData ) => {
		console.log( formData );
		return;
		setSaving( true );
		sendCommand( 'sce_save_convertkit_options', {
			nonce: sceIntegrations.ck_save_nonce,
			...formData,
		} )
			.then( ( ajaxResponse ) => {
				const ajaxData = ajaxResponse.data.data;
				const ajaxSuccess = ajaxResponse.data.success;
				if ( ajaxSuccess ) {
					const { forms, tags } = ajaxData;
					const newFormValues = [];
					forms.forEach( ( keys, index ) => {
						newFormValues.push( keys );
					} );
					const newTagValues = [];
					tags.forEach( ( keys, index ) => {
						newTagValues.push( keys );
					} );
					setValue( 'forms', newFormValues );
					setValue( 'tags', newTagValues );
					setIsSaved( true );
					setTimeout( () => {
						setIsSaved( false );
					}, 3000 );
				} else {
					setError( 'apiKey', { type: 'noForms', message: ajaxData.message } );
				}
			} )
			.catch( ( ajaxResponse ) => {} )
			.then( ( ajaxResponse ) => {
				setSaving( false );
			} );
	};

	const onRefreshCredentials = ( formData ) => {
		setSaving( true );
		sendCommand( 'sce_refresh_convertkit_connection', {
			nonce: sceIntegrations.ck_refresh_nonce,
			...formData,
		} )
			.then( ( ajaxResponse ) => {
				const ajaxData = ajaxResponse.data.data;
				const ajaxSuccess = ajaxResponse.data.success;
				if ( ajaxSuccess ) {
					const { forms, tags, apiValid } = ajaxData;
					const newFormValues = [];
					forms.forEach( ( keys, index ) => {
						newFormValues.push( keys );
					} );
					const newTagValues = [];
					tags.forEach( ( keys, index ) => {
						newTagValues.push( keys );
					} );
					const updatedFormValues = {
						forms: newFormValues,
						tags: newTagValues,
						apiValid,
					};
					reset(
						{ ...formValues, ...updatedFormValues },
						{
							keepErrors: false,
							keepDirty: false,
						}
					);
				} else {
					const updatedFormValues = {
						apiValid: false,
					};
					reset(
						{ ...formValues, ...updatedFormValues },
						{
							keepErrors: false,
							keepDirty: false,
						}
					);
					setError( 'apiKey', { type: 'noForms', message: ajaxData.message } );
					setError( 'secretKey', { type: 'noForms', message: ajaxData.message } );
				}
			} )
			.catch( ( ajaxResponse ) => {} )
			.then( ( ajaxResponse ) => {
				setSaving( false );
			} );
	};

	const onAddTag = ( tagLabel ) => {
		tagLabel = tagLabel.trim();
		if ( '' === tagLabel ) {
			setError( 'tagInput', { type: 'addTagError', message: __( 'Tag name cannot be empty.', 'comment-edit-pro' ) } );
			return;
		}

		// Check to see if label is in use.
		const currentTags = getValues( 'tags' );
		const tagExists = currentTags.find( ( tag ) => tag.label === tagLabel );
		if ( tagExists ) {
			setError( 'tagInput', { type: 'addTagError', message: __( 'Tag name already in use.', 'comment-edit-pro' ) } );
			return;
		}

		// Start adding the tag.
		setIsAddingTag( true );
		sendCommand( 'sce_add_convertkit_tag', {
			nonce: sceIntegrations.ck_add_tag_nonce,
			label: tagLabel,
		} )
			.then( ( ajaxResponse ) => {
				const ajaxData = ajaxResponse.data.data;
				const ajaxSuccess = ajaxResponse.data.success;
				if ( ajaxSuccess ) {
					const { tags } = ajaxData;
					const newTagValues = [];
					tags.forEach( ( keys, index ) => {
						newTagValues.push( keys );
					} );
					setValue( 'tags', newTagValues );
				} else {
					setError( 'tagInput', { type: 'addTagError', message: ajaxData.message } );
				}
			} )
			.catch( ( ajaxResponse ) => {} )
			.then( ( ajaxResponse ) => {
				setIsAddingTag( false );
				tagInput.current.focus();
			} );
	};

	const refreshFormsAndTags = ( formData ) => {
		setSaving( true );
		sendCommand( 'sce_refresh_convertkit_forms_tags', {
			nonce: sceIntegrations.ck_refresh_forms_tags_nonce,
			...formData,
		} )
			.then( ( ajaxResponse ) => {
				const ajaxData = ajaxResponse.data.data;
				const ajaxSuccess = ajaxResponse.data.success;
				if ( ajaxSuccess ) {
					const { forms, tags, apiValid } = ajaxData;
					const newFormValues = [];
					forms.forEach( ( keys, index ) => {
						newFormValues.push( keys );
					} );
					const newTagValues = [];
					tags.forEach( ( keys, index ) => {
						newTagValues.push( keys );
					} );
					const updatedFormValues = {
						forms: newFormValues,
						tags: newTagValues,
						apiValid,
					};
					reset(
						{ ...formValues, ...updatedFormValues },
						{
							keepErrors: false,
							keepDirty: false,
						}
					);
				} else {
					const updatedFormValues = {
						apiValid: false,
					};
					reset(
						{ ...formValues, ...updatedFormValues },
						{
							keepErrors: false,
							keepDirty: false,
						}
					);
					setError( 'apiKey', { type: 'noForms', message: ajaxData.message } );
					setError( 'secretKey', { type: 'noForms', message: ajaxData.message } );
				}
			} )
			.catch( ( ajaxResponse ) => {} )
			.then( ( ajaxResponse ) => {
				setSaving( false );
			} );
	};

	const handleReset = () => {
		setResetting( true );
		sendCommand( 'sce_reset_convertkit_options', {
			nonce: sceIntegrations.reset_nonce,
		} )
			.then( ( ajaxResponse ) => {
				const ajaxData = ajaxResponse.data.data;
				const ajaxSuccess = ajaxResponse.data.success;
				if ( ajaxSuccess ) {
					setIsReset( true );
					reset( {
						enableMailchimp: false,
						mailchimpServerPrefix: '',
						apiKey: '',
						mailchimpLists: [],
						selectedList: '',
						signUpLabel: __( 'Sign Up for Updates', 'comment-edit-pro' ),
					} );
					setTimeout( () => {
						setIsReset( false );
					}, 3000 );
				}
			} )
			.catch( ( ajaxResponse ) => {} )
			.then( ( ajaxResponse ) => {
				setResetting( false );
			} );
	};

	const getNewsletterLabel = () => {
		if ( ! getValues( 'selectedList' ) ) {
			return <></>;
		}
		return (
			<tr>
				<th scope="row">{ __( 'Sign Up Label', 'comment-edit-pro' ) }</th>
				<td>
					<Controller
						name="signUpLabel"
						control={ control }
						rules={ { required: true } }
						render={ ( { field } ) => (
							<TextControl
								{ ...field }
								label={ __( 'Sign-up Label', 'comment-edit-pro' ) }
								className={ classNames( 'sce-admin__text-control', {
									'has-error': 'required' === errors.signUpLabel?.type,
									'is-required': true,
								} ) }
								aria-required="true"
								help={ __(
									'This text will be shown in the comment section when a user leaves a comment.',
									'comment-edit-pro'
								) }
							/>
						) }
					/>
					{ 'required' === errors.signUpLabel?.type && (
						<Notice
							message={ __( 'This field is a required field.' ) }
							status="error"
							politeness="assertive"
							inline={ true }
							icon={ CircularExclamationIcon }
						/>
					) }
				</td>
			</tr>
		);
	};

	const getSignupCheckbox = () => {
		if ( ! getValues( 'selectedList' ) ) {
			return <></>;
		}
		return (
			<tr>
				<th scope="row">{ __( 'Sign Up Checkbox', 'comment-edit-pro' ) }</th>
				<td>
					<Controller
						name="checkboxEnabled"
						control={ control }
						render={ ( { field: { onChange, value } } ) => (
							<ToggleControl
								label={ __( 'Sign Up Checkbox Checked', 'comment-edit-pro' ) }
								className="sce-admin__toggle-control"
								checked={ value }
								onChange={ ( boolValue ) => {
									onChange( boolValue );
								} }
								help={ __(
									'Check the sign-up checkbox by default (not recommended).',
									'comment-edit-pro'
								) }
							/>
						) }
					/>
				</td>
			</tr>
		);
	};

	/**
	 * Gets the form or tag radio option.
	 *
	 * @return {JSX.Element} Form or tags interface.
	 */
	const getFormOrTag = () => {
		if ( needsCredentialRefresh() ) {
			return <></>;
		}
		const forms = getValues( 'forms' );
		const tags = getValues( 'tags' );
		return (
			<tr>
				<th scope="row">{ __( 'Forms or Tags', 'comment-edit-pro' ) }</th>
				<td>
					<Controller
						name="formOrTag"
						control={ control }
						rules={ { required: true } }
						render={ ( { field: { onChange, value } } ) => (
							<>
								<RadioControl
									label={ __(
										'Add Subscribers to Forms or Tags',
										'comment-edit-pro'
									) }
									help={ __(
										'Select whether to add new subscribers to a an existing ConvertKit form or tag(s).',
										'comment-edit-pro'
									) }
									selected={ getValues( 'formOrTag' ) }
									options={ [
										{
											label: __( 'Forms', 'comment-edit-pro' ),
											value: 'form',
										},
										{
											label: __( 'Tags', 'comment-edit-pro' ),
											value: 'tag',
										},
									] }
									onChange={ ( formOrTagValue ) => {
										onChange( formOrTagValue );
									} }
								/>
								<div className="sce-admin-buttons">
									<Button
										variant="tertiary"
										isBusy={ isRefreshingFormsAndTags }
										disabled={ isRefreshingFormsAndTags }
										onClick={ () => {
											setIsRefreshingFormsAndTags( true );
											refreshFormsAndTags();
										} }
										className={ classNames(
											'qdlx__btn qdlx__btn-link qdlx__btn--icon-right',
											{ 'has-error': hasErrors() },
											{ 'has-icon': isRefreshingFormsAndTags },
											{ 'is-saving': isRefreshingFormsAndTags },
										) }
										text={ isRefreshingFormsAndTags ? __( 'Refreshing…', 'comment-edit-pro' ) : __( 'Refresh Forms and Tags', 'comment-edit-pro' ) }
									/>
								</div>
							</>
						) }
					/>
					{ 'form' === getValues( 'formOrTag' ) && forms.length === 0 && (
						<Notice
							message={ __(
								'There are no forms associated with this ConvertKit account and setup cannot continue. Please create a form in ConvertKit or try tags instead.',
								'comment-edit-pro'
							) }
							status="error"
							politeness="assertive"
							inline={ false }
							icon={ CircularExclamationIcon }
						/>
					) }
					{ 'tag' === getValues( 'formOrTag' ) && tags.length === 0 && (
						<Notice
							message={ __(
								'There are no tags available. Try creating a tag below.',
								'comment-edit-pro'
							) }
							status="warning"
							politeness="assertive"
							inline={ false }
							icon={ CircularExclamationIcon }
						/>
					) }
				</td>
			</tr>
		);
	};

	const getConvertKitForms = () => {
		const convertKitForms = getValues( 'forms' );
		if ( convertKitForms.length === 0 ) {
			return <></>;
		}

		return (
			<tr>
				<th scope="row">{ __( 'ConvertKit Forms', 'comment-edit-pro' ) }</th>
				<td>
					<Controller
						name="convertKitForms"
						control={ control }
						rules={ { required: true } }
						render={ ( { field: { onChange, value } } ) => (
							<RadioControl
								label={ __(
									'Select a form for your subscribers',
									'comment-edit-pro'
								) }
								help={ __(
									'Select a default form that will be used when signing up your subscribers.',
									'comment-edit-pro'
								) }
								selected={ getValues( 'selectedForm' ) }
								options={ getValues( 'forms' ) }
								onChange={ ( formSelectedValue ) => {
									onChange( formSelectedValue );
									setValue( 'selectedForm', formSelectedValue );
								} }
							/>
						) }
					/>
					<Controller
						name="selectedForm"
						control={ control }
						rules={ { required: true } }
						render={ ( { field } ) => (
							<TextControl { ...field } type="hidden" aria-hidden="true" />
						) }
					/>
					{ 'required' === errors.selectedForm?.type && (
						<Notice
							message={ __( 'This field is a required field.' ) }
							status="error"
							politeness="assertive"
							inline={ true }
							icon={ CircularExclamationIcon }
						/>
					) }
				</td>
			</tr>
		);
	};

	const getConvertKitTags = () => {
		const convertKitTags = getValues( 'tags' );
		return (
			<tr>
				<th scope="row">{ __( 'ConvertKit Tags', 'comment-edit-pro' ) }</th>
				<td>
					<>
						{ convertKitTags.length > 0 && getValues( 'apiValid' ) &&
						convertKitTags.map( ( tag, index ) => (
							<Controller
								key={ tag.value }
								name={ `tags[${ index }].selected` }
								control={ control }
								render={ ( { field: { onChange, value } } ) => (
									<CheckboxControl
										label={ tag.label }
										onChange={ ( tagSelectedValue ) => {
											onChange( tagSelectedValue );
										} }
										value={ tag.value }
									/>
								) }
							/>
						) ) }
						<div className="sce-convertkit-add-tag">
							<div className="sce-convertkit-add-tag-group">
								<Controller
									name="tagInput"
									control={ control }
									rules={ {
										pattern: /[-_ 0-9A-Za-z]/,
									} }
									render={ ( { field: { onChange, value } } ) => (
										<TextControl
											type="text"
											value={ value }
											onChange={ ( tagInputValue ) => {
												clearErrors( 'tagInput' );
												onChange( tagInputValue );
											} }
											label={ __( 'Add New Tag', 'comment-edit-pro' ) }
											className={ classNames( 'sce-admin__text-control', {
												'has-error': 'required' === errors.tagInput?.type,
											} ) }
											placeholder={ __( 'Tag Name', 'comment-edit-pro' ) }
											aria-required="true"
											ref={ tagInput }
										/>
									) }
								/>
								<div className="sce-admin-buttons">
									<Button
										onClick={ async( e ) => {
											const validationResult = await trigger( 'tagInput' );
											if ( validationResult ) {
												onAddTag( getValues( 'tagInput' ) );
											}
										} }
										className={ classNames(
											'qdlx__btn qdlx__btn-secondary qdlx__btn--icon-right',
										) }
										text={
											isAddingTag
												? __( 'Adding…', 'comment-edit-pro' )
												: __( 'Add New Tag', 'comment-edit-pro' ) }
									/>
								</div>
							</div>
							{ 'pattern' === errors.tagInput?.type && (
								<Notice
									message={ __( 'Special characters are not allowed in tags.', 'comment-edit-pro' ) }
									status="error"
									politeness="assertive"
									inline={ false }
									icon={ CircularExclamationIcon }
								/>
							) }
							{ 'addTagError' === errors.tagInput?.type && (
								<Notice
									message={ errors.tagInput?.message }
									status="error"
									politeness="assertive"
									inline={ false }
									icon={ CircularExclamationIcon }
								/>
							) }
						</div>
					</>
				</td>
			</tr>
		);
	};

	const getAPIKey = () => {
		return (
			<tr>
				<th scope="row">{ __( 'API Key', 'comment-edit-pro' ) }</th>
				<td>
					<Controller
						name="apiKey"
						control={ control }
						rules={ { required: true } }
						render={ ( { field: { onChange, value } } ) => (
							<TextControl
								label={ __( 'ConvertKit API Key', 'comment-edit-pro' ) }
								type="text"
								value={ value }
								onChange={ ( apiKeyValue ) => {
									onChange( apiKeyValue );
									clearErrors();
								} }
								className={ classNames( 'sce-admin__text-control', {
									'has-error': 'required' === errors.apiKey?.type,
									'is-required': true,
								} ) }
								help={ __(
									'Enter your ConvertKit API Key in order to choose a form or tag.',
									'comment-edit-pro'
								) }
								aria-required="true"
							/>
						) }
					/>
					{ 'required' === errors.apiKey?.type && (
						<Notice
							message={ __( 'This field is a required field.' ) }
							status="error"
							politeness="assertive"
							inline={ true }
							icon={ CircularExclamationIcon }
						/>
					) }
					{ 'noForms' === errors.apiKey?.type && (
						<Notice
							message={ errors.apiKey?.message }
							status="error"
							politeness="assertive"
							inline={ true }
							icon={ CircularExclamationIcon }
						/>
					) }
				</td>
			</tr>
		);
	};

	const getSecretKey = () => {
		return (
			<tr>
				<th scope="row">{ __( 'Secret Key', 'comment-edit-pro' ) }</th>
				<td>
					<Controller
						name="secretKey"
						control={ control }
						rules={ { required: true } }
						render={ ( { field: { onChange, value } } ) => (
							<TextControl
								label={ __( 'ConvertKit Secret Key', 'comment-edit-pro' ) }
								type="text"
								value={ value }
								onChange={ ( secretKey ) => {
									onChange( secretKey );
									clearErrors();
								} }
								className={ classNames( 'sce-admin__text-control', {
									'has-error': 'required' === errors.secretKey?.type,
									'is-required': true,
								} ) }
								help={ __(
									'Enter your ConvertKit Secret Key in order to choose a form or tag.',
									'comment-edit-pro'
								) }
								aria-required="true"
							/>
						) }
					/>
					{ 'required' === errors.secretKey?.type && (
						<Notice
							message={ __( 'This field is a required field.' ) }
							status="error"
							politeness="assertive"
							inline={ true }
							icon={ CircularExclamationIcon }
						/>
					) }
					{ 'noForms' === errors.secretKey?.type && (
						<Notice
							message={ errors.secretKey?.message }
							status="error"
							politeness="assertive"
							inline={ true }
							icon={ CircularExclamationIcon }
						/>
					) }
				</td>
			</tr>
		);
	};

	const getSaveIcon = () => {
		if ( saving ) {
			return Spinner;
		}
		if ( isSaved ) {
			return ClipboardCheck;
		}
		return false;
	};

	const getSaveText = () => {
		if ( saving ) {
			return __( 'Saving…', 'comment-edit-pro' );
		}
		if ( isSaved ) {
			return __( 'Saved', 'comment-edit-pro' );
		}
		return __( 'Save ConvertKit Options', 'comment-edit-pro' );
	};

	const getRefreshCredentialsText = () => {
		if ( saving ) {
			return __( 'Connecting…', 'comment-edit-pro' );
		}
		if ( isSaved ) {
			return __( 'Connected', 'comment-edit-pro' );
		}
		return __( 'Connect to ConvertKit', 'comment-edit-pro' );
	};

	const getResetText = () => {
		if ( resetting ) {
			return __( 'Disconnecting…', 'comment-edit-pro' );
		}
		if ( isReset ) {
			return __( 'Disconnected', 'comment-edit-pro' );
		}
		return __( 'Disconnect From ConvertKit', 'comment-edit-pro' );
	};

	return (
		<>
			<h2>
				{ __( 'ConvertKit', 'comment-edit-pro' ) }{ ' ' }
				<a
					className="sce-admin-heading-docs"
					target="_blank"
					rel="noreferrer"
					href="https://docs.dlxplugins.com/v/comment-edit-pro/features-overview/integrations/mailchimp-integration"
				>
					({ __( 'Docs', 'comment-edit-pro' ) })
				</a>
			</h2>
			<p className="description">
				{ __(
					'When someone leaves a comment, they can be given the option to subscribe to your ConvertKit account.',
					'comment-edit-pro'
				) }
			</p>
			<form
				onSubmit={ handleSubmit( ( submitData, e ) => {
					e.preventDefault();
					if ( ! needsCredentialRefresh() ) {
						onSubmit( submitData );
					} else {
						onRefreshCredentials( submitData );
					}
				} ) }
			>
				<table className="form-table">
					<tbody>
						<tr>
							<th scope="row">{ __( 'ConvertKit', 'comment-edit-pro' ) }</th>
							<td>
								<Controller
									name="enableConvertKit"
									control={ control }
									render={ ( { field: { onChange, value } } ) => (
										<ToggleControl
											label={ __( 'Enable ConvertKit', 'comment-edit-pro' ) }
											className="sce-admin__toggle-control"
											checked={ value }
											onChange={ ( boolValue ) => {
												//setShowButtonOptions( boolValue );
												onChange( boolValue );
											} }
											help={ __(
												'Enable or Disable the ConvertKit Integration.',
												'comment-edit-pro'
											) }
										/>
									) }
								/>
							</td>
						</tr>
						{ getValues( 'enableConvertKit' ) && (
							<>
								{ getAPIKey() }
								{ getSecretKey() }
								{ getFormOrTag() }
								{ getConvertKitForms() }
								{ getConvertKitTags() }
								{ getNewsletterLabel() }
								{ getSignupCheckbox() }
							</>
						) }
					</tbody>
				</table>
				<div className="sce-admin-buttons">
					{ getValues( 'apiValid' ) && canShowSaveButton() && (
						<Button
							className={ classNames(
								'qdlx__btn qdlx__btn-primary qdlx__btn--icon-right',
								{ 'has-error': hasErrors() },
								{ 'has-icon': saving || isSaved },
								{ 'is-saving': saving && ! isSaved },
								{ 'is-saved': isSaved }
							) }
							type="submit"
							text={ getSaveText() }
							icon={ getSaveIcon() }
							iconSize="18"
							iconPosition="right"
							disabled={ saving }
						/>
					) }
					{ needsCredentialRefresh() && (
						<Button
							className={ classNames(
								'qdlx__btn qdlx__btn-primary qdlx__btn--icon-right',
								{ 'has-error': hasErrors() }
							) }
							type="submit"
							text={ getRefreshCredentialsText() }
							icon={ false }
							disabled={ credentialsRefreshing }
						/>
					) }
					{ ! needsCredentialRefresh() && (
						<Button
							className={ classNames(
								'qdlx__btn qdlx__btn-danger qdlx__btn--icon-right',
								{ 'has-icon': resetting },
								{ 'is-resetting': { resetting } }
							) }
							type="button"
							text={ getResetText() }
							icon={ resetting ? Spinner : false }
							iconSize="18"
							iconPosition="right"
							disabled={ saving || resetting }
							onClick={ ( e ) => {
								setResetting( true );
								handleReset( e );
							} }
						/>
					) }
				</div>
				{ hasErrors() && (
					<Notice
						message={ __(
							'There are form validation errors. Please correct them above.',
							'comment-edit-pro'
						) }
						status="error"
						politeness="polite"
					/>
				) }
				{ isSaved && (
					<Notice
						message={ __( 'Your settings have been saved.', 'comment-edit-pro' ) }
						status="success"
						politeness="assertive"
					/>
				) }
				{ isReset && (
					<Notice
						message={ __( 'Your settings have been reset.', 'comment-edit-pro' ) }
						status="success"
						politeness="assertive"
					/>
				) }
			</form>
		</>
	);
};
export default ConvertKit;
